const PatchSource = "import { parsePatchFiles } from "@pierre/diffs";
import { DiffView } from "@/registry/erbium/blocks/diff-view";

const patch = `diff --git a/settings.json b/settings.json
--- a/settings.json
+++ b/settings.json
@@ -1,3 +1,4 @@
 {
-  "theme": "light"
+  "theme": "system",
+  "wrap": true
 }
`;

const fileDiff = parsePatchFiles(patch, "settings-patch", true)[0]?.files[0];

const Example = () => {
